func makeCounter() -> () -> Int {
    var n = 0
    return { n += 1; return n }        // escaping by return, captures var
}

final class VC {
    var onTap: (() -> Void)?
    func install() {
        onTap = { [weak self] in self?.handleTap() }   // breaks the retain cycle
    }
}

func runNow(_ body: () -> Void) {}      // non-escaping: cannot be stored
func runLater(_ body: @escaping () -> Void) {}
